-- RC6 lane D2: THE AFTER PROJECTION, read only. What the lane's code will
-- write, emulated in SQL on today's production rows and GENERATED from the
-- code's own tables (bettor_market_family.EQUIVALENCE, the market plane's
-- period line specs, ontology LEAGUE_SPORT / NON_SPORTS_LEAGUES /
-- AMBIGUOUS_LEAGUE_CODES), so it restates nothing by hand:
--   P1 every never-attested line contract's new settlement reading;
--   P2 the slug-grammar fix: registry rows that leave the sports universe
--      (non-sports codes), outrights that gain a sport, ambiguous codes.
-- A contract whose settlement basis is a decision record keeps it.
\echo === P1. line contracts: before (production settlement_why, truncated) -> after (projected), never-attested only ===
WITH p AS MATERIALIZED (
  SELECT g.contract_id, g.market_type, g.settlement_basis, g.settlement_why,
         lower(regexp_replace(translate(coalesce(r.rules_text, ''),
               E'’−–—', E'''---'), '\s+', ' ', 'g'))
           AS flat,
         CASE WHEN g.contract_id ~ '-(neg|pos)-[0-9]+pt[0-9]+$'
              THEN (CASE WHEN g.contract_id ~ '-neg-[0-9]+pt[0-9]+$' THEN -1 ELSE 1 END)
                   * (substring(g.contract_id from '-(?:neg|pos)-([0-9]+)pt[0-9]+$')
                      || '.' || substring(g.contract_id from '-(?:neg|pos)-[0-9]+pt([0-9]+)$'))::float8
              WHEN g.contract_id ~ '-[0-9]+pt[0-9]+$' AND g.market_type !~ '_spread$'
              THEN (substring(g.contract_id from '-([0-9]+)pt[0-9]+$') || '.'
                    || substring(g.contract_id from '-[0-9]+pt([0-9]+)$'))::float8
         END AS slug_line,
         (g.contract_id ~ 'pt5$') AS half_point
    FROM market_plane_registry g
    LEFT JOIN market_plane_rules r USING (contract_id)
   WHERE g.active AND g.venue = 'POLYMARKET_US'
     AND g.market_type IN ('football_team_full_game_spread', 'football_team_full_game_total', 'football_team_points_full_game_total', 'hockey_team_full_game_spread', 'hockey_team_full_game_total', 'hockey_team_total_goals', 'basketball_team_full_game_spread', 'basketball_team_full_game_total', 'baseball_team_full_game_spread', 'baseball_team_full_game_total', 'baseball_team_total_runs', 'soccer_team_full_game_spread', 'soccer_team_full_game_total', 'tennis_match_games_spread', 'tennis_match_total_games', 'football_team_first_half_spread', 'football_team_second_half_spread', 'football_team_first_quarter_spread', 'football_team_second_quarter_spread', 'football_team_third_quarter_spread', 'football_team_fourth_quarter_spread', 'football_game_first_half_total', 'football_game_second_half_total', 'football_game_first_quarter_total', 'football_game_second_quarter_total', 'football_game_third_quarter_total', 'football_game_fourth_quarter_total', 'football_team_first_half_total', 'football_team_second_half_total', 'hockey_team_first_period_spread', 'hockey_team_second_period_spread', 'hockey_team_third_period_spread', 'hockey_team_first_period_total', 'hockey_team_second_period_total', 'hockey_team_third_period_total', 'soccer_team_first_half_spread', 'soccer_team_second_half_spread', 'soccer_team_first_half_total', 'soccer_team_second_half_total')
     AND coalesce(g.settlement_basis, '') NOT IN ('DECISION_ATTEST',
                                                  'DECISION_PRICED_SETTLEMENT_DIFFERENCE')),
q AS (
  SELECT p.*, CASE WHEN p.market_type = 'football_team_full_game_spread' THEN CASE WHEN p.slug_line IS NULL THEN 'VENUE_LINE_CONTRACT_LINE_NOT_READABLE:football/spread' WHEN NOT p.half_point THEN 'LINE_NOT_A_HALF_POINT_PUSH_HANDLING_NOT_PROVEN_EQUIVALENT:football/spread' WHEN coalesce(p.flat, '') = '' THEN 'VENUE_LINE_RULES_TEXT_NOT_READ:football/spread' WHEN p.flat ~ '\yovertime (?:is|will be) (?:not included|excluded)\y' OR p.flat ~ '\yexclud\w* (?:any )?overtime\y' OR p.flat ~ '\yregulation (?:time )?only\y' THEN 'VENUE_LINE_TEXT_CONFLICTS_WITH_THE_BOOK_GRADING:football/spread' WHEN NOT (p.flat ~ '\ywill settle to yes if (?:the )?(?:.+?) covers? an? ([-+]?\d+(?:\.\d+)?) point spread in the\y' AND p.flat ~ '\yovertime is included if played\y') THEN 'VENUE_LINE_TEXT_DOES_NOT_STATE_THE_CAPTURED_TERMS:football/spread' WHEN NOT coalesce((substring(p.flat from '\ywill settle to yes if (?:the )?(?:.+?) covers? an? ([-+]?\d+(?:\.\d+)?) point spread in the\y'))::float8 = p.slug_line, false) THEN 'VENUE_LINE_TEXT_LINE_DIFFERS_FROM_THE_CONTRACT_LINE:football/spread' WHEN p.flat !~ 'last[ -]+fair[ -]+market[ -]+price' THEN 'LINE_VENUE_TEXT_STATES_NO_EXCEPTIONAL_RULE:football/spread' ELSE 'LINE_EXCEPTIONAL_SETTLEMENT_TERMS_DIFFER:football/spread:SETTLEMENT_DIFFERENCE_MARKET_NOT_A_MONEY_LINE' END
           WHEN p.market_type = 'football_team_full_game_total' THEN CASE WHEN p.slug_line IS NULL THEN 'VENUE_LINE_CONTRACT_LINE_NOT_READABLE:football/total' WHEN NOT p.half_point THEN 'LINE_NOT_A_HALF_POINT_PUSH_HANDLING_NOT_PROVEN_EQUIVALENT:football/total' WHEN coalesce(p.flat, '') = '' THEN 'VENUE_LINE_RULES_TEXT_NOT_READ:football/total' WHEN p.flat ~ '\yovertime (?:is|will be) (?:not included|excluded)\y' OR p.flat ~ '\yexclud\w* (?:any )?overtime\y' OR p.flat ~ '\yregulation (?:time )?only\y' THEN 'VENUE_LINE_TEXT_CONFLICTS_WITH_THE_BOOK_GRADING:football/total' WHEN NOT (p.flat ~ '\ywill settle to yes if .+? combine for over ([-+]?\d+(?:\.\d+)?) points in the\y' AND p.flat ~ '\yovertime is included if played\y') THEN 'VENUE_LINE_TEXT_DOES_NOT_STATE_THE_CAPTURED_TERMS:football/total' WHEN NOT coalesce(abs((substring(p.flat from '\ywill settle to yes if .+? combine for over ([-+]?\d+(?:\.\d+)?) points in the\y'))::float8) = abs(p.slug_line), false) THEN 'VENUE_LINE_TEXT_LINE_DIFFERS_FROM_THE_CONTRACT_LINE:football/total' WHEN p.flat !~ 'last[ -]+fair[ -]+market[ -]+price' THEN 'LINE_VENUE_TEXT_STATES_NO_EXCEPTIONAL_RULE:football/total' ELSE 'LINE_EXCEPTIONAL_SETTLEMENT_TERMS_DIFFER:football/total:SETTLEMENT_DIFFERENCE_MARKET_NOT_A_MONEY_LINE' END
           WHEN p.market_type = 'football_team_points_full_game_total' THEN CASE WHEN p.slug_line IS NULL THEN 'VENUE_LINE_CONTRACT_LINE_NOT_READABLE:football/team_total' WHEN NOT p.half_point THEN 'LINE_NOT_A_HALF_POINT_PUSH_HANDLING_NOT_PROVEN_EQUIVALENT:football/team_total' WHEN coalesce(p.flat, '') = '' THEN 'VENUE_LINE_RULES_TEXT_NOT_READ:football/team_total' WHEN p.flat ~ '\yovertime (?:is|will be) (?:not included|excluded)\y' OR p.flat ~ '\yexclud\w* (?:any )?overtime\y' OR p.flat ~ '\yregulation (?:time )?only\y' THEN 'VENUE_LINE_TEXT_CONFLICTS_WITH_THE_BOOK_GRADING:football/team_total' WHEN NOT (p.flat ~ '\ysettles over if (?:the )?(?:.+?) scores? more than ([-+]?\d+(?:\.\d+)?) points in the full game of the\y' AND p.flat ~ '\yovertime is included if played\y') THEN 'VENUE_LINE_TEXT_DOES_NOT_STATE_THE_CAPTURED_TERMS:football/team_total' WHEN NOT coalesce(abs((substring(p.flat from '\ysettles over if (?:the )?(?:.+?) scores? more than ([-+]?\d+(?:\.\d+)?) points in the full game of the\y'))::float8) = abs(p.slug_line), false) THEN 'VENUE_LINE_TEXT_LINE_DIFFERS_FROM_THE_CONTRACT_LINE:football/team_total' WHEN p.flat !~ 'last[ -]+fair[ -]+market[ -]+price' THEN 'LINE_VENUE_TEXT_STATES_NO_EXCEPTIONAL_RULE:football/team_total' ELSE 'LINE_EXCEPTIONAL_SETTLEMENT_TERMS_DIFFER:football/team_total:SETTLEMENT_DIFFERENCE_MARKET_NOT_A_MONEY_LINE' END
           WHEN p.market_type = 'hockey_team_full_game_spread' THEN CASE WHEN p.slug_line IS NULL THEN 'VENUE_LINE_CONTRACT_LINE_NOT_READABLE:hockey/spread' WHEN NOT p.half_point THEN 'LINE_NOT_A_HALF_POINT_PUSH_HANDLING_NOT_PROVEN_EQUIVALENT:hockey/spread' WHEN coalesce(p.flat, '') = '' THEN 'VENUE_LINE_RULES_TEXT_NOT_READ:hockey/spread' WHEN p.flat ~ '\yovertime (?:is|will be) (?:not included|excluded)\y' OR p.flat ~ '\yexclud\w* (?:any )?overtime\y' OR p.flat ~ '\yregulation (?:time )?only\y' OR p.flat ~ '\yshootout (?:does|will) not count\y' OR p.flat ~ '\yexclud\w* (?:the |any )?shootout\y' THEN 'VENUE_LINE_TEXT_CONFLICTS_WITH_THE_BOOK_GRADING:hockey/spread' WHEN NOT (p.flat ~ '\ywill settle to yes if (?:the )?(?:.+?) covers? an? ([-+]?\d+(?:\.\d+)?) goal spread in the\y' AND p.flat ~ '\yovertime is included if played\y' AND p.flat ~ '\yif a shootout determines the winner, the shootout will count as one goal for the winning team\y') THEN 'VENUE_LINE_TEXT_DOES_NOT_STATE_THE_CAPTURED_TERMS:hockey/spread' WHEN NOT coalesce((substring(p.flat from '\ywill settle to yes if (?:the )?(?:.+?) covers? an? ([-+]?\d+(?:\.\d+)?) goal spread in the\y'))::float8 = p.slug_line, false) THEN 'VENUE_LINE_TEXT_LINE_DIFFERS_FROM_THE_CONTRACT_LINE:hockey/spread' WHEN p.flat !~ 'last[ -]+fair[ -]+market[ -]+price' THEN 'LINE_VENUE_TEXT_STATES_NO_EXCEPTIONAL_RULE:hockey/spread' ELSE 'LINE_EXCEPTIONAL_SETTLEMENT_TERMS_DIFFER:hockey/spread:SETTLEMENT_DIFFERENCE_MARKET_NOT_A_MONEY_LINE' END
           WHEN p.market_type = 'hockey_team_full_game_total' THEN CASE WHEN p.slug_line IS NULL THEN 'VENUE_LINE_CONTRACT_LINE_NOT_READABLE:hockey/total' WHEN NOT p.half_point THEN 'LINE_NOT_A_HALF_POINT_PUSH_HANDLING_NOT_PROVEN_EQUIVALENT:hockey/total' WHEN coalesce(p.flat, '') = '' THEN 'VENUE_LINE_RULES_TEXT_NOT_READ:hockey/total' WHEN p.flat ~ '\yovertime (?:is|will be) (?:not included|excluded)\y' OR p.flat ~ '\yexclud\w* (?:any )?overtime\y' OR p.flat ~ '\yregulation (?:time )?only\y' OR p.flat ~ '\yshootout (?:does|will) not count\y' OR p.flat ~ '\yexclud\w* (?:the |any )?shootout\y' THEN 'VENUE_LINE_TEXT_CONFLICTS_WITH_THE_BOOK_GRADING:hockey/total' WHEN NOT (p.flat ~ '\ywill settle to yes if .+? combine for over ([-+]?\d+(?:\.\d+)?) goals in the\y' AND p.flat ~ '\yovertime is included if played\y' AND p.flat ~ '\yif a shootout determines the winner, the shootout will count as one goal for the winning team\y') THEN 'VENUE_LINE_TEXT_DOES_NOT_STATE_THE_CAPTURED_TERMS:hockey/total' WHEN NOT coalesce(abs((substring(p.flat from '\ywill settle to yes if .+? combine for over ([-+]?\d+(?:\.\d+)?) goals in the\y'))::float8) = abs(p.slug_line), false) THEN 'VENUE_LINE_TEXT_LINE_DIFFERS_FROM_THE_CONTRACT_LINE:hockey/total' WHEN p.flat !~ 'last[ -]+fair[ -]+market[ -]+price' THEN 'LINE_VENUE_TEXT_STATES_NO_EXCEPTIONAL_RULE:hockey/total' ELSE 'LINE_EXCEPTIONAL_SETTLEMENT_TERMS_DIFFER:hockey/total:SETTLEMENT_DIFFERENCE_MARKET_NOT_A_MONEY_LINE' END
           WHEN p.market_type = 'hockey_team_total_goals' THEN CASE WHEN p.slug_line IS NULL THEN 'VENUE_LINE_CONTRACT_LINE_NOT_READABLE:hockey/team_total' WHEN NOT p.half_point THEN 'LINE_NOT_A_HALF_POINT_PUSH_HANDLING_NOT_PROVEN_EQUIVALENT:hockey/team_total' WHEN coalesce(p.flat, '') = '' THEN 'VENUE_LINE_RULES_TEXT_NOT_READ:hockey/team_total' WHEN p.flat ~ '\yovertime (?:is|will be) (?:not included|excluded)\y' OR p.flat ~ '\yexclud\w* (?:any )?overtime\y' OR p.flat ~ '\yregulation (?:time )?only\y' OR p.flat ~ '\yshootout (?:does|will) not count\y' OR p.flat ~ '\yexclud\w* (?:the |any )?shootout\y' THEN 'VENUE_LINE_TEXT_CONFLICTS_WITH_THE_BOOK_GRADING:hockey/team_total' WHEN NOT (p.flat ~ '\ywill settle to yes if (?:the )?(?:.+?) scores? over ([-+]?\d+(?:\.\d+)?) goals in the\y' AND p.flat ~ '\yovertime is included if played\y' AND p.flat ~ '\yif a shootout determines the winner, the shootout will count as one goal for the winning team\y') THEN 'VENUE_LINE_TEXT_DOES_NOT_STATE_THE_CAPTURED_TERMS:hockey/team_total' WHEN NOT coalesce(abs((substring(p.flat from '\ywill settle to yes if (?:the )?(?:.+?) scores? over ([-+]?\d+(?:\.\d+)?) goals in the\y'))::float8) = abs(p.slug_line), false) THEN 'VENUE_LINE_TEXT_LINE_DIFFERS_FROM_THE_CONTRACT_LINE:hockey/team_total' WHEN p.flat !~ 'last[ -]+fair[ -]+market[ -]+price' THEN 'LINE_VENUE_TEXT_STATES_NO_EXCEPTIONAL_RULE:hockey/team_total' ELSE 'LINE_EXCEPTIONAL_SETTLEMENT_TERMS_DIFFER:hockey/team_total:SETTLEMENT_DIFFERENCE_MARKET_NOT_A_MONEY_LINE' END
           WHEN p.market_type = 'basketball_team_full_game_spread' THEN CASE WHEN p.slug_line IS NULL THEN 'VENUE_LINE_CONTRACT_LINE_NOT_READABLE:basketball/spread' WHEN NOT p.half_point THEN 'LINE_NOT_A_HALF_POINT_PUSH_HANDLING_NOT_PROVEN_EQUIVALENT:basketball/spread' WHEN coalesce(p.flat, '') = '' THEN 'VENUE_LINE_RULES_TEXT_NOT_READ:basketball/spread' WHEN p.flat ~ '\yovertime (?:is|will be) (?:not included|excluded)\y' OR p.flat ~ '\yexclud\w* (?:any )?overtime\y' OR p.flat ~ '\yregulation (?:time )?only\y' THEN 'VENUE_LINE_TEXT_CONFLICTS_WITH_THE_BOOK_GRADING:basketball/spread' WHEN NOT (p.flat ~ '\ywill settle to yes if (?:the )?(?:.+?) covers? an? ([-+]?\d+(?:\.\d+)?) point spread in the\y' AND p.flat ~ '\yovertime is included if played\y') THEN 'VENUE_LINE_TEXT_DOES_NOT_STATE_THE_CAPTURED_TERMS:basketball/spread' WHEN NOT coalesce((substring(p.flat from '\ywill settle to yes if (?:the )?(?:.+?) covers? an? ([-+]?\d+(?:\.\d+)?) point spread in the\y'))::float8 = p.slug_line, false) THEN 'VENUE_LINE_TEXT_LINE_DIFFERS_FROM_THE_CONTRACT_LINE:basketball/spread' WHEN p.flat !~ 'last[ -]+fair[ -]+market[ -]+price' THEN 'LINE_VENUE_TEXT_STATES_NO_EXCEPTIONAL_RULE:basketball/spread' ELSE 'LINE_EXCEPTIONAL_SETTLEMENT_TERMS_DIFFER:basketball/spread:SETTLEMENT_DIFFERENCE_MARKET_NOT_A_MONEY_LINE' END
           WHEN p.market_type = 'basketball_team_full_game_total' THEN CASE WHEN p.slug_line IS NULL THEN 'VENUE_LINE_CONTRACT_LINE_NOT_READABLE:basketball/total' WHEN NOT p.half_point THEN 'LINE_NOT_A_HALF_POINT_PUSH_HANDLING_NOT_PROVEN_EQUIVALENT:basketball/total' WHEN coalesce(p.flat, '') = '' THEN 'VENUE_LINE_RULES_TEXT_NOT_READ:basketball/total' WHEN p.flat ~ '\yovertime (?:is|will be) (?:not included|excluded)\y' OR p.flat ~ '\yexclud\w* (?:any )?overtime\y' OR p.flat ~ '\yregulation (?:time )?only\y' THEN 'VENUE_LINE_TEXT_CONFLICTS_WITH_THE_BOOK_GRADING:basketball/total' WHEN NOT (p.flat ~ '\ywill settle to yes if .+? combine for over ([-+]?\d+(?:\.\d+)?) points in the\y' AND p.flat ~ '\yovertime is included if played\y') THEN 'VENUE_LINE_TEXT_DOES_NOT_STATE_THE_CAPTURED_TERMS:basketball/total' WHEN NOT coalesce(abs((substring(p.flat from '\ywill settle to yes if .+? combine for over ([-+]?\d+(?:\.\d+)?) points in the\y'))::float8) = abs(p.slug_line), false) THEN 'VENUE_LINE_TEXT_LINE_DIFFERS_FROM_THE_CONTRACT_LINE:basketball/total' WHEN p.flat !~ 'last[ -]+fair[ -]+market[ -]+price' THEN 'LINE_VENUE_TEXT_STATES_NO_EXCEPTIONAL_RULE:basketball/total' ELSE 'LINE_EXCEPTIONAL_SETTLEMENT_TERMS_DIFFER:basketball/total:SETTLEMENT_DIFFERENCE_MARKET_NOT_A_MONEY_LINE' END
           WHEN p.market_type = 'baseball_team_full_game_spread' THEN CASE WHEN p.slug_line IS NULL THEN 'VENUE_LINE_CONTRACT_LINE_NOT_READABLE:baseball/spread' WHEN NOT p.half_point THEN 'LINE_NOT_A_HALF_POINT_PUSH_HANDLING_NOT_PROVEN_EQUIVALENT:baseball/spread' WHEN coalesce(p.flat, '') = '' THEN 'VENUE_LINE_RULES_TEXT_NOT_READ:baseball/spread' WHEN p.flat ~ '\yextra innings (?:are|will be) (?:not included|excluded)\y' OR p.flat ~ '\yexclud\w* (?:any )?extra innings\y' OR p.flat ~ '\yafter (?:nine|9) innings only\y' THEN 'VENUE_LINE_TEXT_CONFLICTS_WITH_THE_BOOK_GRADING:baseball/spread' WHEN NOT (p.flat ~ '\ywill settle to yes if (?:the )?(?:.+?) covers? an? ([-+]?\d+(?:\.\d+)?) run spread in the\y' AND p.flat ~ '\yextra innings are included if played\y') THEN 'VENUE_LINE_TEXT_DOES_NOT_STATE_THE_CAPTURED_TERMS:baseball/spread' WHEN NOT coalesce((substring(p.flat from '\ywill settle to yes if (?:the )?(?:.+?) covers? an? ([-+]?\d+(?:\.\d+)?) run spread in the\y'))::float8 = p.slug_line, false) THEN 'VENUE_LINE_TEXT_LINE_DIFFERS_FROM_THE_CONTRACT_LINE:baseball/spread' WHEN p.flat !~ 'last[ -]+fair[ -]+market[ -]+price' THEN 'LINE_VENUE_TEXT_STATES_NO_EXCEPTIONAL_RULE:baseball/spread' ELSE 'LINE_EXCEPTIONAL_SETTLEMENT_TERMS_DIFFER:baseball/spread:SETTLEMENT_DIFFERENCE_MARKET_NOT_A_MONEY_LINE' END
           WHEN p.market_type = 'baseball_team_full_game_total' THEN CASE WHEN p.slug_line IS NULL THEN 'VENUE_LINE_CONTRACT_LINE_NOT_READABLE:baseball/total' WHEN NOT p.half_point THEN 'LINE_NOT_A_HALF_POINT_PUSH_HANDLING_NOT_PROVEN_EQUIVALENT:baseball/total' WHEN coalesce(p.flat, '') = '' THEN 'VENUE_LINE_RULES_TEXT_NOT_READ:baseball/total' WHEN p.flat ~ '\yextra innings (?:are|will be) (?:not included|excluded)\y' OR p.flat ~ '\yexclud\w* (?:any )?extra innings\y' OR p.flat ~ '\yafter (?:nine|9) innings only\y' THEN 'VENUE_LINE_TEXT_CONFLICTS_WITH_THE_BOOK_GRADING:baseball/total' WHEN NOT (p.flat ~ '\ywill settle to yes if .+? combine for over ([-+]?\d+(?:\.\d+)?) runs in the\y' AND p.flat ~ '\yextra innings are included if played\y') THEN 'VENUE_LINE_TEXT_DOES_NOT_STATE_THE_CAPTURED_TERMS:baseball/total' WHEN NOT coalesce(abs((substring(p.flat from '\ywill settle to yes if .+? combine for over ([-+]?\d+(?:\.\d+)?) runs in the\y'))::float8) = abs(p.slug_line), false) THEN 'VENUE_LINE_TEXT_LINE_DIFFERS_FROM_THE_CONTRACT_LINE:baseball/total' WHEN p.flat !~ 'last[ -]+fair[ -]+market[ -]+price' THEN 'LINE_VENUE_TEXT_STATES_NO_EXCEPTIONAL_RULE:baseball/total' ELSE 'LINE_EXCEPTIONAL_SETTLEMENT_TERMS_DIFFER:baseball/total:SETTLEMENT_DIFFERENCE_MARKET_NOT_A_MONEY_LINE' END
           WHEN p.market_type = 'baseball_team_total_runs' THEN CASE WHEN p.slug_line IS NULL THEN 'VENUE_LINE_CONTRACT_LINE_NOT_READABLE:baseball/team_total' WHEN NOT p.half_point THEN 'LINE_NOT_A_HALF_POINT_PUSH_HANDLING_NOT_PROVEN_EQUIVALENT:baseball/team_total' WHEN coalesce(p.flat, '') = '' THEN 'VENUE_LINE_RULES_TEXT_NOT_READ:baseball/team_total' WHEN p.flat ~ '\yextra innings (?:are|will be) (?:not included|excluded)\y' OR p.flat ~ '\yexclud\w* (?:any )?extra innings\y' OR p.flat ~ '\yafter (?:nine|9) innings only\y' THEN 'VENUE_LINE_TEXT_CONFLICTS_WITH_THE_BOOK_GRADING:baseball/team_total' WHEN NOT (p.flat ~ '\ywill settle to yes if (?:the )?(?:.+?) scores? over ([-+]?\d+(?:\.\d+)?) runs in the\y' AND p.flat ~ '\yextra innings are included if played\y') THEN 'VENUE_LINE_TEXT_DOES_NOT_STATE_THE_CAPTURED_TERMS:baseball/team_total' WHEN NOT coalesce(abs((substring(p.flat from '\ywill settle to yes if (?:the )?(?:.+?) scores? over ([-+]?\d+(?:\.\d+)?) runs in the\y'))::float8) = abs(p.slug_line), false) THEN 'VENUE_LINE_TEXT_LINE_DIFFERS_FROM_THE_CONTRACT_LINE:baseball/team_total' WHEN p.flat !~ 'last[ -]+fair[ -]+market[ -]+price' THEN 'LINE_VENUE_TEXT_STATES_NO_EXCEPTIONAL_RULE:baseball/team_total' ELSE 'LINE_EXCEPTIONAL_SETTLEMENT_TERMS_DIFFER:baseball/team_total:SETTLEMENT_DIFFERENCE_MARKET_NOT_A_MONEY_LINE' END
           WHEN p.market_type = 'soccer_team_full_game_spread' THEN 'BOOKMAKER_TERMS_NOT_HELD:BOOK_MARKET_RULES_SECTION_NOT_CAPTURED:soccer/spread'
           WHEN p.market_type = 'soccer_team_full_game_total' THEN 'BOOKMAKER_TERMS_NOT_HELD:BOOK_MARKET_RULES_SECTION_NOT_CAPTURED:soccer/total'
           WHEN p.market_type = 'tennis_match_games_spread' THEN 'BOOKMAKER_TERMS_NOT_HELD:BOOK_RULES_FOR_THIS_SPORT_NOT_CAPTURED:tennis/spread'
