           WHEN p.market_type = 'hockey_team_third_period_spread' THEN CASE WHEN p.slug_line IS NULL THEN 'VENUE_LINE_CONTRACT_LINE_NOT_READABLE:hockey/spread@P3' WHEN NOT p.half_point THEN 'LINE_NOT_A_HALF_POINT_PUSH_HANDLING_NOT_PROVEN_EQUIVALENT:hockey/spread@P3' WHEN coalesce(p.flat, '') = '' THEN 'VENUE_LINE_RULES_TEXT_NOT_READ:hockey/spread@P3' WHEN p.flat ~ '\yovertime is included if played\y' THEN 'VENUE_LINE_TEXT_CONFLICTS_WITH_THE_BOOK_GRADING:hockey/spread@P3' WHEN NOT (p.flat ~ '\ywill settle to yes if (?:the )?(?:.+?) covers? an? ([-+]?\d+(?:\.\d+)?) goal spread in the third period of the\y' AND p.flat ~ '\yovertime and any shootout are not included\y') THEN 'VENUE_LINE_TEXT_DOES_NOT_STATE_THE_CAPTURED_TERMS:hockey/spread@P3' WHEN NOT coalesce((substring(p.flat from '\ywill settle to yes if (?:the )?(?:.+?) covers? an? ([-+]?\d+(?:\.\d+)?) goal spread in the third period of the\y'))::float8 = p.slug_line, false) THEN 'VENUE_LINE_TEXT_LINE_DIFFERS_FROM_THE_CONTRACT_LINE:hockey/spread@P3' WHEN p.flat !~ 'last[ -]+fair[ -]+market[ -]+price' THEN 'LINE_VENUE_TEXT_STATES_NO_EXCEPTIONAL_RULE:hockey/spread@P3' ELSE 'LINE_EXCEPTIONAL_SETTLEMENT_TERMS_DIFFER:hockey/spread@P3:SETTLEMENT_DIFFERENCE_MARKET_NOT_A_MONEY_LINE' END
           WHEN p.market_type = 'hockey_team_first_period_total' THEN CASE WHEN p.slug_line IS NULL THEN 'VENUE_LINE_CONTRACT_LINE_NOT_READABLE:hockey/total@P1' WHEN NOT p.half_point THEN 'LINE_NOT_A_HALF_POINT_PUSH_HANDLING_NOT_PROVEN_EQUIVALENT:hockey/total@P1' WHEN coalesce(p.flat, '') = '' THEN 'VENUE_LINE_RULES_TEXT_NOT_READ:hockey/total@P1' WHEN false THEN 'VENUE_LINE_TEXT_CONFLICTS_WITH_THE_BOOK_GRADING:hockey/total@P1' WHEN NOT (p.flat ~ '\ywill settle to yes if .+? combine for over ([-+]?\d+(?:\.\d+)?) goals during the first period in the\y' AND true) THEN 'VENUE_LINE_TEXT_DOES_NOT_STATE_THE_CAPTURED_TERMS:hockey/total@P1' WHEN NOT coalesce(abs((substring(p.flat from '\ywill settle to yes if .+? combine for over ([-+]?\d+(?:\.\d+)?) goals during the first period in the\y'))::float8) = abs(p.slug_line), false) THEN 'VENUE_LINE_TEXT_LINE_DIFFERS_FROM_THE_CONTRACT_LINE:hockey/total@P1' WHEN p.flat !~ 'last[ -]+fair[ -]+market[ -]+price' THEN 'LINE_VENUE_TEXT_STATES_NO_EXCEPTIONAL_RULE:hockey/total@P1' ELSE 'LINE_EXCEPTIONAL_SETTLEMENT_TERMS_DIFFER:hockey/total@P1:SETTLEMENT_DIFFERENCE_MARKET_NOT_A_MONEY_LINE' END
           WHEN p.market_type = 'hockey_team_second_period_total' THEN CASE WHEN p.slug_line IS NULL THEN 'VENUE_LINE_CONTRACT_LINE_NOT_READABLE:hockey/total@P2' WHEN NOT p.half_point THEN 'LINE_NOT_A_HALF_POINT_PUSH_HANDLING_NOT_PROVEN_EQUIVALENT:hockey/total@P2' WHEN coalesce(p.flat, '') = '' THEN 'VENUE_LINE_RULES_TEXT_NOT_READ:hockey/total@P2' WHEN false THEN 'VENUE_LINE_TEXT_CONFLICTS_WITH_THE_BOOK_GRADING:hockey/total@P2' WHEN NOT (p.flat ~ '\ywill settle to yes if .+? combine for over ([-+]?\d+(?:\.\d+)?) goals during the second period in the\y' AND true) THEN 'VENUE_LINE_TEXT_DOES_NOT_STATE_THE_CAPTURED_TERMS:hockey/total@P2' WHEN NOT coalesce(abs((substring(p.flat from '\ywill settle to yes if .+? combine for over ([-+]?\d+(?:\.\d+)?) goals during the second period in the\y'))::float8) = abs(p.slug_line), false) THEN 'VENUE_LINE_TEXT_LINE_DIFFERS_FROM_THE_CONTRACT_LINE:hockey/total@P2' WHEN p.flat !~ 'last[ -]+fair[ -]+market[ -]+price' THEN 'LINE_VENUE_TEXT_STATES_NO_EXCEPTIONAL_RULE:hockey/total@P2' ELSE 'LINE_EXCEPTIONAL_SETTLEMENT_TERMS_DIFFER:hockey/total@P2:SETTLEMENT_DIFFERENCE_MARKET_NOT_A_MONEY_LINE' END
           WHEN p.market_type = 'hockey_team_third_period_total' THEN CASE WHEN p.slug_line IS NULL THEN 'VENUE_LINE_CONTRACT_LINE_NOT_READABLE:hockey/total@P3' WHEN NOT p.half_point THEN 'LINE_NOT_A_HALF_POINT_PUSH_HANDLING_NOT_PROVEN_EQUIVALENT:hockey/total@P3' WHEN coalesce(p.flat, '') = '' THEN 'VENUE_LINE_RULES_TEXT_NOT_READ:hockey/total@P3' WHEN p.flat ~ '\yovertime is included if played\y' THEN 'VENUE_LINE_TEXT_CONFLICTS_WITH_THE_BOOK_GRADING:hockey/total@P3' WHEN NOT (p.flat ~ '\ywill settle to yes if .+? combine for over ([-+]?\d+(?:\.\d+)?) goals during the third period in the\y' AND p.flat ~ '\yovertime and any shootout are not included\y') THEN 'VENUE_LINE_TEXT_DOES_NOT_STATE_THE_CAPTURED_TERMS:hockey/total@P3' WHEN NOT coalesce(abs((substring(p.flat from '\ywill settle to yes if .+? combine for over ([-+]?\d+(?:\.\d+)?) goals during the third period in the\y'))::float8) = abs(p.slug_line), false) THEN 'VENUE_LINE_TEXT_LINE_DIFFERS_FROM_THE_CONTRACT_LINE:hockey/total@P3' WHEN p.flat !~ 'last[ -]+fair[ -]+market[ -]+price' THEN 'LINE_VENUE_TEXT_STATES_NO_EXCEPTIONAL_RULE:hockey/total@P3' ELSE 'LINE_EXCEPTIONAL_SETTLEMENT_TERMS_DIFFER:hockey/total@P3:SETTLEMENT_DIFFERENCE_MARKET_NOT_A_MONEY_LINE' END
           WHEN p.market_type = 'soccer_team_first_half_spread' THEN 'BOOKMAKER_TERMS_NOT_HELD:BOOK_MARKET_RULES_SECTION_NOT_CAPTURED:soccer/spread@FIRST_HALF'
           WHEN p.market_type = 'soccer_team_second_half_spread' THEN 'BOOKMAKER_TERMS_NOT_HELD:BOOK_MARKET_RULES_SECTION_NOT_CAPTURED:soccer/spread@SECOND_HALF'
           WHEN p.market_type = 'soccer_team_first_half_total' THEN 'BOOKMAKER_TERMS_NOT_HELD:BOOK_MARKET_RULES_SECTION_NOT_CAPTURED:soccer/total@FIRST_HALF'
           WHEN p.market_type = 'soccer_team_second_half_total' THEN 'BOOKMAKER_TERMS_NOT_HELD:BOOK_MARKET_RULES_SECTION_NOT_CAPTURED:soccer/total@SECOND_HALF'
           END AS after_why
    FROM p)
SELECT market_type, left(coalesce(settlement_why, '<null>'), 60) AS before_why,
       left(after_why, 120) AS after_why, count(*) AS n
  FROM q GROUP BY 1, 2, 3 ORDER BY 1, 4 DESC;
\echo === P1b. line contracts on a decision record (unchanged by the lane) ===
SELECT market_type, settlement_basis, left(settlement_why, 70) AS why, count(*) AS n
  FROM market_plane_registry
 WHERE active AND venue = 'POLYMARKET_US' AND market_type IN ('football_team_full_game_spread', 'football_team_full_game_total', 'football_team_points_full_game_total', 'hockey_team_full_game_spread', 'hockey_team_full_game_total', 'hockey_team_total_goals', 'basketball_team_full_game_spread', 'basketball_team_full_game_total', 'baseball_team_full_game_spread', 'baseball_team_full_game_total', 'baseball_team_total_runs', 'soccer_team_full_game_spread', 'soccer_team_full_game_total', 'tennis_match_games_spread', 'tennis_match_total_games', 'football_team_first_half_spread', 'football_team_second_half_spread', 'football_team_first_quarter_spread', 'football_team_second_quarter_spread', 'football_team_third_quarter_spread', 'football_team_fourth_quarter_spread', 'football_game_first_half_total', 'football_game_second_half_total', 'football_game_first_quarter_total', 'football_game_second_quarter_total', 'football_game_third_quarter_total', 'football_game_fourth_quarter_total', 'football_team_first_half_total', 'football_team_second_half_total', 'hockey_team_first_period_spread', 'hockey_team_second_period_spread', 'hockey_team_third_period_spread', 'hockey_team_first_period_total', 'hockey_team_second_period_total', 'hockey_team_third_period_total', 'soccer_team_first_half_spread', 'soccer_team_second_half_spread', 'soccer_team_first_half_total', 'soccer_team_second_half_total')
   AND settlement_basis IN ('DECISION_ATTEST', 'DECISION_PRICED_SETTLEMENT_DIFFERENCE')
 GROUP BY 1, 2, 3 ORDER BY 1, 4 DESC;
\echo === P2. slug grammar: active POLYMARKET_US rows by projected league class ===
WITH ls(code, sport) AS (VALUES ('acle','soccer'), ('afcq','soccer'), ('arg2','soccer'), ('atp','tennis'), ('atpdb','tennis'), ('bel1','soccer'), ('bra','soccer'), ('brb','soccer'), ('btla','efootball'), ('bun','soccer'), ('bun2','soccer'), ('cbb','basketball'), ('cfb','football'), ('cnl','soccer'), ('cs2','esports'), ('czechligapro','table_tennis'), ('dota2','esports'), ('dpwt','golf'), ('dwcs','mma'), ('ebattlesefpl','efootball'), ('ebattlesefsa','efootball'), ('ebattlesefwca','efootball'), ('ebattlesefwcb','efootball'), ('efl1','soccer'), ('efl2','soccer'), ('eflch','soccer'), ('ekst','soccer'), ('engnl','soccer'), ('epl','soccer'), ('euroleague','basketball'), ('f1','motorsport'), ('idnsl','soccer'), ('intf','soccer'), ('itfme','tennis'), ('itfwo','tennis'), ('j1','soccer'), ('j2','soccer'), ('kbo','baseball'), ('kft','golf'), ('khl','hockey'), ('lal','soccer'), ('lg1','soccer'), ('ligpor','soccer'), ('liv','golf'), ('lmx','soccer'), ('lol','esports'), ('lpa','soccer'), ('mlb','baseball'), ('mls','soccer'), ('nascar','motorsport'), ('nba','basketball'), ('ncaams','soccer'), ('ncaaws','soccer'), ('nfl','football'), ('nhl','hockey'), ('npb','baseball'), ('par1','soccer'), ('par2','soccer'), ('pga','golf'), ('pgatc','golf'), ('r6','esports'), ('sea','soccer'), ('serca','soccer'), ('sercb','soccer'), ('sercc','soccer'), ('setkamecz','table_tennis'), ('setkamemd','table_tennis'), ('setkameua','table_tennis'), ('setkawoua','table_tennis'), ('shl','hockey'), ('tff1','soccer'), ('ttcup','table_tennis'), ('u21eq','soccer'), ('ucl','soccer'), ('uecl','soccer'), ('uel','soccer'), ('ufc','mma'), ('ufl','football'), ('unl','soccer'), ('uslc','soccer'), ('utr','tennis'), ('uwwcq','soccer'), ('valorant','esports'), ('vkl','efootball'), ('wnba','basketball'), ('wta','tennis')),
r AS (
  SELECT g.contract_id, g.market_type, g.coverage_state, g.coverage_why,
         CASE WHEN split_part(g.event_id, '-', 1) IN ('atc','aec','asc','tsc','astatc','cpc')
              THEN split_part(g.event_id, '-', 2) ELSE split_part(g.event_id, '-', 1) END AS lg
    FROM market_plane_registry g WHERE g.active AND g.venue = 'POLYMARKET_US')
SELECT CASE WHEN r.lg IN ('bcb', 'boc', 'boe', 'boi', 'boj', 'box', 'btc', 'cbr', 'cut', 'ecb', 'emmys', 'eth', 'fed', 'grammys', 'gtasc', 'hike', 'nobel', 'ntflx', 'oscars', 'pol', 'sol', 'temp', 'us', 'uscpi', 'uscpicore', 'usfed', 'usgas', 'usnfp', 'usunemp') THEN 'LEAVES_THE_SPORTS_UNIVERSE_NON_SPORTS_CODE'
            WHEN r.market_type = 'futures' AND r.lg IN ('wbc') THEN 'OUTRIGHT_LEAGUE_CODE_AMBIGUOUS'
            WHEN r.market_type = 'futures' AND ls.code IS NOT NULL THEN 'OUTRIGHT_GAINS_SPORT_' || upper(ls.sport)
            WHEN r.market_type = 'futures' THEN 'OUTRIGHT_CODE_NOT_IN_LEAGUE_SPORT:' || r.lg
            ELSE 'TYPED_ROW_LEAGUE_NOW_THE_EVENT_CODE' END AS projected,
       r.coverage_state, count(*) AS n
  FROM r LEFT JOIN ls ON ls.code = r.lg
 GROUP BY 1, 2 ORDER BY 3 DESC LIMIT 80;
